    using namespace std;
    class Fraction {
         int _numerator, _denominator;
    public:
         Fraction(int n = 0, int d = 1) {
             _numerator = n;
             _denominator = d;
         }
         Fraction(const Fraction& f) {
             _numerator = f._numerator;
             _denominator = f._denominator;
         }
    };
    int main()
    {
         Fraction f_1;
         Fraction f_2(f_1);
         return 0;
